'use client';

/**
 * Progress page — animated analysis pipeline for a repository.
 * Mock: specs/001-code-wiki/ux/docs-glassmorphism/progress.html
 */

import { useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { useParams, useSearchParams, useRouter } from 'next/navigation';
import { GradientBackground } from '@/components/ui/GradientBackground';
import { GlassCard } from '@/components/ui/GlassCard';
import { Logo } from '@/components/ui/Logo';
import { api } from '@/services/api';
import type { Repository } from '@/services/api';

const PIPELINE_STEPS = [
  { label: 'Cloning repository', doneDesc: 'Done' },
  { label: 'Parsing source files', doneDesc: 'Files analyzed' },
  { label: 'Detecting modules', activeDesc: 'Modules found…' },
  { label: 'Building knowledge graph', pendingDesc: 'Pending' },
  { label: 'Generating wiki pages', pendingDesc: 'Pending' },
  { label: 'Creating visual diagrams', pendingDesc: 'Pending' },
];

// Progress percentage per step (cumulative)
const STEP_PROGRESS = [10, 25, 45, 65, 85, 100];

type StepState = 'complete' | 'active' | 'pending';

function getStepStates(activeIndex: number): StepState[] {
  return PIPELINE_STEPS.map((_, i) => {
    if (i < activeIndex) return 'complete';
    if (i === activeIndex) return 'active';
    return 'pending';
  });
}

export default function ProgressPage() {
  const params = useParams();
  const searchParams = useSearchParams();
  const router = useRouter();

  const owner = params.owner as string;
  const name = params.name as string;
  const repoId = searchParams.get('id') ?? '';

  const [repo, setRepo] = useState<Repository | null>(null);
  const [activeStep, setActiveStep] = useState(2); // mock: on step 3 (idx 2)
  const [accordionOpen, setAccordionOpen] = useState(false);
  const [done, setDone] = useState(false);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Poll repo status every 5s
  useEffect(() => {
    if (!repoId) return;

    const poll = async () => {
      try {
        const r = await api.repositories.get(repoId);

      const r = await api.repositories.get(repoId);
      setRepo(r);
      if (r.status === 'ready') {
        clearInterval(pollRef.current!);
        setActiveStep(PIPELINE_STEPS.length); // all complete
        setDone(true);
      } else if (r.status === 'error') {
        clearInterval(pollRef.current!);
      }
    } catch {
      // ignore polling errors
    }
  };

  poll();
  pollRef.current = setInterval(poll, 5000);
  return () => clearInterval(pollRef.current!);
}, [repoId]);

// Simulate step progression every 8s when no repoId (demo mode)
useEffect(() => {
  if (repoId) return;
  const timer = setInterval(() => {
    setActiveStep((s) => {
      if (s >= PIPELINE_STEPS.length - 1) {
        clearInterval(timer);
        setDone(true);
        return PIPELINE_STEPS.length;
      }
      return s + 1;
    });
  }, 8000);
  return () => clearInterval(timer);
}, [repoId]);

const stepStates = getStepStates(Math.min(activeStep, PIPELINE_STEPS.length - 1));
const pct = done ? 100 : STEP_PROGRESS[Math.min(activeStep, STEP_PROGRESS.length - 1)] ?? 10;
const displayName = repo?.name ?? name;
const displayUrl = repo?.url ?? `github.com/${owner}/${name}`;

const MOCK_MODULES = [
  { icon: '📦', name: 'authentication', count: '24 functions' },
  { icon: '📦', name: 'api/routes', count: '18 functions' },
  { icon: '📦', name: 'database', count: '12 functions' },
  { icon: '📦', name: 'utils', count: '31 functions' },
  { icon: '📦', name: 'middleware', count: '9 functions' },
];

if (done) {
  return (

    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    animation-delay: -5s;
}

@keyframes float {
    0%, 100% {
        transform: translate(0, 0) scale(1);
    }
    33% {
        transform: translate(50px, -50px) scale(1.1);
    }
    66% {
        transform: translate(-30px, 30px) scale(0.9);
    }
}

/* Layout */
.chat-container {
    max-width: 1400px;
    margin: 0 auto;
    height: 100vh;
    display: flex;
    flex-direction: column;
    padding: 24px;
    gap: 24px;
}

/* Glass Card Base */
.glass-card {
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
}

/* Header */
.chat-header {
    padding: 24px 32px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 16px;
    opacity: 0;
    animation: fadeInUp 0.6s ease forwards;
}

.header-left {
    display: flex;
    align-items: center;
    gap: 20px;
}

.logo {
    display: flex;
    align-items: center;
    gap: 12px;
    text-decoration: none;
}

.logo-icon {
    width: 44px;
    height: 44px;
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 18px;
    box-shadow: 0 0 30px rgba(139, 92, 246, 0.5);
}

.logo-text {
    font-size: 20px;
    font-weight: 700;
    background: linear-gradient(135deg, var(--primary-light), var(--secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.chat-title {
    font-size: 20px;
    font-weight: 700;
    color: var(--text-primary);
}

.header-actions {
    display: flex;
    gap: 12px;
}

.header-btn {
    padding: 10px 20px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid var(--glass-border);
    border-radius: 10px;
    color: var(--text-primary);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
}

.header-btn:hover {
    background: rgba(139, 92, 246, 0.2);
    border-color: rgba(139, 92, 246, 0.5);
}

.new-chat-btn {
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    border: none;
    box-shadow: 0 4px 20px rgba(139, 92, 246, 0.3);
}

.new-chat-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 30px rgba(139, 92, 246, 0.5);
}

/* Chat Messages */
.chat-messages {
    flex: 1;
    padding: 32px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 24px;
    opacity: 0;
    animation: fadeInUp 0.8s 0.2s ease forwards;
}

.chat-messages::-webkit-scrollbar {
    width: 8px;
}

.chat-messages::-webkit-scrollbar-track {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 4px;
}

.chat-messages::-webkit-scrollbar-thumb {
    background: var(--primary);
    border-radius: 4px;
}

.message {
    display: flex;
    gap: 16px;
    align-items: flex-start;
    animation: messageSlideIn 0.4s ease;
}

@keyframes messageSlideIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.message-avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    flex-shrink: 0;
}

.user-avatar {
    background: linear-gradient(135deg, var(--accent), var(--primary));
    box-shadow: 0 0 20px rgba(236, 72, 153, 0.4);
}

.ai-avatar {
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    box-shadow: 0 0 20px rgba(139, 92, 246, 0.4);
}

.message-content {
    flex: 1;
    max-width: 800px;
}

.message-bubble {
    padding: 20px 24px;
    border-radius: 16px;
    font-size: 15px;
    line-height: 1.7;

/**
 * Typed API client for the Code Wiki backend.
 * All methods map 1:1 to openapi.yaml operationIds.
 */

const BASE_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000/v1";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface Pagination {
  page: number;
  limit: number;
  total_pages: number;
  total_items: number;
}

export interface Repository {
  id: string;
  url: string;
  name: string;
  owner: string;
  primary_languages: string[];
  size_lines?: number;
  size_files?: number;
  last_analyzed_commit?: string;
  last_analyzed_at?: string;
  status: "pending" | "analyzing" | "ready" | "error";
  access_level?: "public" | "private";
  created_at: string;
  updated_at: string;
}

export interface Wiki {
  id: string;
  repository_id: string;
  home_page_id?: string;
  structure_version?: number;
  module_count?: number;
  page_count?: number;
  status: "generating" | "ready" | "updating";
  generated_at?: string;
  updated_at?: string;
}

export interface WikiPage {
  id: string;
  wiki_id?: string;
  page_type: "home" | "module" | "getting_started" | "function_index" | "glossary" | "api_reference";
  title: string;
  slug: string;

  slug: string;
  content: Record<string, unknown>;
  related_page_ids: string[];
  source_files: string[];
  commit_hash?: string;
  created_at?: string;
  updated_at?: string;
}

export interface Module {
  id: string;
  wiki_id?: string;
  wiki_page_id?: string;
  name: string;
  slug: string;
  file_paths: string[];
  file_count?: number;
  line_count?: number;
  description?: string;
  detection_confidence?: number;
  dependencies_module_ids: string[];
  created_at?: string;
}

export interface CodeEntityRelationships {
  calls: string[];
  imports: string[];
  inherits_from: string[];
}

export interface CodeEntity {
  id: string;
  module_id?: string;
  entity_type: "function" | "class" | "method" | "module" | "file" | "variable";
  name: string;
  qualified_name: string;
  file_path: string;
  line_number: number;
  signature?: string;
  description?: string;
  docstring?: string;
  visibility?: "public" | "private" | "protected";
  relationships?: CodeEntityRelationships;
}

export interface ChatMessageReference {
  type: "wiki_page" | "code_entity" | "file";
  id: string;
  title: string;
}

export interface ChatMessage {
  role: "user" | "assistant";
  content: string;
  timestamp: string;
  references: ChatMessageReference[];
}

export interface ChatConversation {
  id: string;
  user_id?: string;
  repository_id: string;
  messages: ChatMessage[];
  created_at?: string;
  updated_at?: string;
}

export interface UpdateEvent {
  id: string;
  repository_id: string;
  commit_hash: string;
  changed_files: string[];
  affected_module_ids: string[];
  status: "pending" | "processing" | "completed" | "failed";
  started_at?: string;
  completed_at?: string;
  error_message?: string;
}

export interface SearchResultItem {
  type: "page" | "entity" | "module";
  id: string;
  title: string;
  snippet?: string;
  score?: number;
}

export interface SearchResults {
  query: string;
  total_results: number;
  results: SearchResultItem[];
}

export interface ApiError {
  code: string;
  message: string;
  details?: unknown;
}

// ─── HTTP helper ─────────────────────────────────────────────────────────────

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
    ...init,
  });

  if (!res.ok) {
    const err: ApiError = await res.json().catch(() => ({
      code: "UNKNOWN",
      message: res.statusText,
    }));
    throw Object.assign(new Error(err.message), { status: res.status, ...err });
  }

  if (res.status === 204) return undefined as T;
  return res.json() as Promise<T>;
}

// ─── Repositories ─────────────────────────────────────────────────────────────

export const repositories = {
  create: (url: string, access_token?: string) =>
    request<Repository>("/repositories", {
      method: "POST",
      body: JSON.stringify({ url, access_token }),
    }),

  list: (params?: { status?: Repository["status"]; page?: number; limit?: number }) => {
    const qs = new URLSearchParams();
    if (params?.status) qs.set("status", params.status);
    if (params?.page) qs.set("page", String(params.page));
    if (params?.limit) qs.set("limit", String(params.limit));
    return request<{ repositories: Repository[]; pagination: Pagination }>(
      `/repositories?${qs.toString()}`
    );
  },

  get: (id: string) => request<Repository>(`/repositories/${id}`),

  delete: (id: string) => request<void>(`/repositories/${id}`, { method: "DELETE" }),

  refresh: (id: string) =>
    request<UpdateEvent>(`/repositories/${id}/refresh`, { method: "POST" }),
};

// ─── Wikis ────────────────────────────────────────────────────────────────────

export const wikis = {
  get: (repositoryId: string) => request<Wiki>(`/wikis/${repositoryId}`),

  listPages: (repositoryId: string, pageType?: WikiPage["page_type"]) => {
    const qs = pageType ? `?page_type=${pageType}` : "";
    return request<WikiPage[]>(`/wikis/${repositoryId}/pages${qs}`);
  },

  getPage: (repositoryId: string, slug: string) =>
    request<WikiPage>(`/wikis/${repositoryId}/pages/${slug}`),

  listModules: (repositoryId: string) =>
    request<Module[]>(`/wikis/${repositoryId}/modules`),

  getModule: (repositoryId: string, slug: string) =>
    request<Module>(`/wikis/${repositoryId}/modules/${slug}`),

  getEntity: (repositoryId: string, qualifiedName: string) =>
    request<CodeEntity>(`/wikis/${repositoryId}/entities/${qualifiedName}`),
};

// ─── Chat ─────────────────────────────────────────────────────────────────────

export const chat = {
  createConversation: (repositoryId: string) =>
    request<ChatConversation>(`/chat/${repositoryId}/conversations`, { method: "POST" }),

  listConversations: (repositoryId: string) =>
    request<ChatConversation[]>(`/chat/${repositoryId}/conversations`),

  sendMessage: (conversationId: string, content: string) =>
    request<ChatMessage>(`/chat/conversations/${conversationId}/messages`, {
      method: "POST",
      body: JSON.stringify({ content }),
    }),
};

// ─── Search ───────────────────────────────────────────────────────────────────

export const search = {
  query: (
    repositoryId: string,
    q: string,
    type: "all" | "pages" | "entities" | "modules" = "all",
    limit = 20
  ) => {
    const qs = new URLSearchParams({ q, type, limit: String(limit) });
    return request<SearchResults>(`/search/${repositoryId}?${qs.toString()}`);
  },
};

// ─── Unified namespace ────────────────────────────────────────────────────────

