          border: '1px solid var(--glass-border)',
          display: 'flex',
          alignItems: 'center',
          gap: 6,
        }}
      >
        {[0, 1, 2].map((i) => (
          <span
            key={i}
            style={{
              width: 8, height: 8, borderRadius: '50%',
              background: 'var(--primary)',
              animation: `dotPulse 1.4s ${i * 0.2}s ease-in-out infinite`,
              display: 'inline-block',
            }}
          />
        ))}
      </div>
    </div>
  );
}

