'use client';

/**
 * Visual Diagrams page — architecture, dependency graph, module relationships.
 * Mock: specs/001-code-wiki/ux/docs-glassmorphism/diagrams.html
 */

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { GradientBackground } from '@/components/ui/GradientBackground';
import { GlassCard } from '@/components/ui/GlassCard';
import { Logo } from '@/components/ui/Logo';
import { api } from '@/services/api';
import type { DiagramData, DiagramNode, DiagramsResponse, Repository } from '@/services/api';

type TabId = 'architecture' | 'dependency_graph' | 'module_relationships';

const TABS: { id: TabId; label: string; icon: string }[] = [
  { id: 'architecture', label: 'Architecture', icon: '🏗️' },
  { id: 'dependency_graph', label: 'Dependency Graph', icon: '🕸️' },
  { id: 'module_relationships', label: 'Module Relationships', icon: '🔗' },
];

// Color map: matches glassmorphism design system colors
const NODE_COLORS: Record<string, { bg: string; border: string; shadow: string }> = {
  purple: {
    bg: 'linear-gradient(135deg, rgba(139,92,246,0.3), rgba(139,92,246,0.1))',
    border: 'rgba(139,92,246,0.4)',
    shadow: 'rgba(139,92,246,0.25)',
  },
  cyan: {
    bg: 'linear-gradient(135deg, rgba(6,182,212,0.3), rgba(6,182,212,0.1))',
    border: 'rgba(6,182,212,0.4)',
    shadow: 'rgba(6,182,212,0.25)',
  },
  pink: {
    bg: 'linear-gradient(135deg, rgba(236,72,153,0.3), rgba(236,72,153,0.1))',
    border: 'rgba(236,72,153,0.4)',
    shadow: 'rgba(236,72,153,0.25)',
  },
  green: {
    bg: 'linear-gradient(135deg, rgba(34,197,94,0.3), rgba(34,197,94,0.1))',
    border: 'rgba(34,197,94,0.4)',
    shadow: 'rgba(34,197,94,0.2)',
  },
  amber: {
    bg: 'linear-gradient(135deg, rgba(245,158,11,0.3), rgba(245,158,11,0.1))',
    border: 'rgba(245,158,11,0.4)',
    shadow: 'rgba(245,158,11,0.2)',
  },
};

const COLORS_LIST = ['purple', 'cyan', 'pink', 'green', 'amber'];

function nodeColors(color?: string) {
  return NODE_COLORS[color ?? 'purple'] ?? NODE_COLORS.purple;
}

/** Architecture tab — node grid with tier rows */
function ArchitectureTab({ data, base }: { data: DiagramData; base: string }) {
  if (data.nodes.length === 0) return <EmptyState />;
  return (
    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 16, padding: 8 }}>
      {data.nodes.map((node) => {
        const c = nodeColors(node.color);
        return (
          <Link
            key={node.id}
            href={node.slug ? `${base}/modules/${node.slug}` : '#'}
            style={{
              minWidth: 160,
              padding: '16px 20px',
              background: c.bg,
              border: `1px solid ${c.border}`,
              borderRadius: 16,
              boxShadow: `0 0 20px ${c.shadow}`,
              textDecoration: 'none',
              transition: 'transform 0.2s, box-shadow 0.2s',
              display: 'flex',
              flexDirection: 'column',
              gap: 6,
            }}
          >
            <div
              style={{
                width: 40, height: 40,
                borderRadius: 10,
                background: c.bg,
                border: `1px solid ${c.border}`,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: 20, marginBottom: 4,
              }}
            >
              {node.icon ?? '📦'}
            </div>
            <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-primary)' }}>
              {node.label}
            </div>
            <div style={{ fontSize: 11, color: 'var(--text-tertiary)', fontFamily: "'Fira Code', monospace" }}>
              {node.sublabel ?? (node.file_count ? `${node.file_count} files` : '')}
            </div>
            {node.tier && (
              <div style={{ fontSize: 10, color: 'var(--text-tertiary)', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                {node.tier}
              </div>
            )}
          </Link>
        );
      })}
    </div>
  );
}

/** Dependency graph tab — bubble nodes */
function DependencyGraphTab({ data, base }: { data: DiagramData; base: string }) {
  if (data.nodes.length === 0) return <EmptyState />;
  return (
    <div
      style={{
        display: 'flex',
        flexWrap: 'wrap',
        gap: 20,
        padding: 16,
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: 300,
      }}
    >
      {data.nodes.map((node) => {
        const c = nodeColors(node.color);
        const size = 80 + Math.min((node.call_count ?? 0) * 4, 40);
        return (
          <Link
            key={node.id}
            href={node.slug ? `${base}/modules/${node.slug}` : '#'}
            title={node.label}
            style={{
              width: size, height: size,
              borderRadius: '50%',
              background: `radial-gradient(circle at 30% 30%, ${c.bg}, rgba(0,0,0,0.1))`,
              border: `2px solid ${c.border}`,
              boxShadow: `0 0 30px ${c.shadow}`,
              display: 'flex', flexDirection: 'column',
              alignItems: 'center', justifyContent: 'center',
              textDecoration: 'none',
              transition: 'transform 0.2s',
              padding: 8,
              textAlign: 'center',
            }}
          >
            <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--text-primary)', lineHeight: 1.3 }}>
              {node.label.length > 12 ? node.label.slice(0, 10) + '…' : node.label}
            </div>
          </Link>
        );
      })}
    </div>
  );
}

/** Module relationships tab — compact cards with connection indicators */
function ModuleRelationshipsTab({ data, base }: { data: DiagramData; base: string }) {
  if (data.nodes.length === 0) return <EmptyState />;

  // Build adjacency for quick lookup
  const edgeMap = new Map<string, string[]>();
  for (const edge of data.edges) {
    if (!edgeMap.has(edge.from_)) edgeMap.set(edge.from_, []);
    edgeMap.get(edge.from_)!.push(edge.to);
  }

  return (
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 16, padding: 8 }}>
      {data.nodes.map((node) => {
        const c = nodeColors(node.color);
        const deps = edgeMap.get(node.id) ?? [];
        return (
          <Link
            key={node.id}
            href={node.slug ? `${base}/modules/${node.slug}` : '#'}
            style={{
              padding: '16px 18px',
              background: c.bg,
              border: `1px solid ${c.border}`,
              borderRadius: 14,
              boxShadow: `0 0 16px ${c.shadow}`,
              textDecoration: 'none',
              transition: 'transform 0.2s',
              display: 'flex',
              flexDirection: 'column',
              gap: 8,
            }}
          >
            <div style={{ fontSize: 14, fontWeight: 700, color: 'var(--text-primary)' }}>{node.label}</div>
            <div style={{ fontSize: 11, color: 'var(--text-tertiary)' }}>
              {node.sublabel ?? (node.file_count ? `${node.file_count} files` : '')}
            </div>
            {deps.length > 0 && (
              <div style={{ fontSize: 11, color: 'var(--secondary)', marginTop: 4 }}>
                → {deps.length} dep{deps.length !== 1 ? 's' : ''}
              </div>
            )}
          </Link>
        );
      })}
    </div>
  );
}

function EmptyState() {
  return (
    <div style={{ textAlign: 'center', padding: '60px 20px', color: 'var(--text-tertiary)' }}>
      <div style={{ fontSize: 40, marginBottom: 12 }}>🔍</div>
      <div>No diagram data available. Run a full analysis first.</div>
    </div>
  );
}

// MOCK data used when API returns nothing
const MOCK_DIAGRAMS: DiagramsResponse = {
  architecture: {
    nodes: [
      { id: '1', label: 'Web Client', sublabel: 'React / TypeScript', color: 'purple', icon: '🌐', tier: 'frontend', slug: '' },
      { id: '2', label: 'API Gateway', sublabel: 'src/gateway/', color: 'cyan', icon: '🔌', tier: 'api', slug: '' },
      { id: '3', label: 'Auth Service', sublabel: 'src/auth/', color: 'pink', icon: '🔐', tier: 'service', slug: '' },
      { id: '4', label: 'Wiki Generator', sublabel: 'src/wiki/', color: 'purple', icon: '📄', tier: 'service', slug: '' },
      { id: '5', label: 'PostgreSQL', sublabel: 'Primary DB', color: 'green', icon: '🗄️', tier: 'data', slug: '' },
      { id: '6', label: 'Qdrant', sublabel: 'Vector DB', color: 'cyan', icon: '🔮', tier: 'data', slug: '' },
    ],
    edges: [
      { from_: '1', to: '2', label: 'HTTP/REST' },
      { from_: '2', to: '3', label: 'auth' },
      { from_: '2', to: '4', label: 'wiki' },
      { from_: '4', to: '5', label: 'SQL' },
      { from_: '4', to: '6', label: 'vectors' },
    ],
  },
  dependency_graph: {
    nodes: [
      { id: '1', label: 'auth', color: 'purple', call_count: 12, slug: '' },
      { id: '2', label: 'api', color: 'cyan', call_count: 8, slug: '' },
      { id: '3', label: 'wiki', color: 'pink', call_count: 6, slug: '' },
      { id: '4', label: 'database', color: 'green', call_count: 4, slug: '' },
      { id: '5', label: 'utils', color: 'amber', call_count: 2, slug: '' },
    ],
    edges: [
      { from_: '1', to: '4', rel_type: 'CALLS', weight: 5 },
      { from_: '2', to: '1', rel_type: 'CALLS', weight: 3 },
      { from_: '3', to: '4', rel_type: 'CALLS', weight: 2 },
    ],
  },
  module_relationships: {
    nodes: [
      { id: '1', label: 'Authentication', sublabel: '18 files', color: 'purple', slug: '' },
      { id: '2', label: 'API Routes', sublabel: '14 files', color: 'cyan', slug: '' },
      { id: '3', label: 'Database', sublabel: '10 files', color: 'green', slug: '' },
      { id: '4', label: 'Wiki Engine', sublabel: '22 files', color: 'pink', slug: '' },
    ],
    edges: [
      { from_: '1', to: '3', label: 'uses' },
      { from_: '2', to: '1', label: 'uses' },
      { from_: '4', to: '3', label: 'uses' },
    ],
  },
};

export default function DiagramsPage() {
  const params = useParams();
  const owner = params.owner as string;
  const name = params.name as string;
  const base = `/${owner}/${name}`;

  const [activeTab, setActiveTab] = useState<TabId>('architecture');
  const [diagrams, setDiagrams] = useState<DiagramsResponse>(MOCK_DIAGRAMS);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        const { repositories } = await api.repositories.list();
        const found = repositories.find(
          (r) => r.owner?.toLowerCase() === owner.toLowerCase() && r.name.toLowerCase() === name.toLowerCase()
        );
        if (!found) { setLoading(false); return; }

        const data = await api.wikis.getDiagrams(found.id).catch(() => null);
        if (data) setDiagrams(data);
      } catch {
        // fall back to mock
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [owner, name]);

  const activeData = diagrams[activeTab];

  return (
    <>
      <GradientBackground />
      <div style={{ maxWidth: 1200, margin: '0 auto', padding: '24px', minHeight: '100vh' }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 24 }}>
          <Logo href={base} />
          <div>
            <h1 style={{ fontSize: 24, fontWeight: 800, letterSpacing: '-0.02em' }}>Visual Diagrams</h1>
            <div style={{ fontSize: 13, color: 'var(--text-tertiary)' }}>{owner}/{name}</div>
          </div>
          <Link
            href={base}
            style={{
              marginLeft: 'auto',
              padding: '8px 16px',
              background: 'rgba(255,255,255,0.05)',
              border: '1px solid var(--glass-border)',
              borderRadius: 10,
              color: 'var(--text-secondary)',
              fontSize: 13,
              fontWeight: 600,
              textDecoration: 'none',
            }}
          >
            ← Wiki
          </Link>
        </div>

        {/* Tab bar */}
        <GlassCard style={{ padding: '6px', display: 'flex', gap: 4, marginBottom: 20, borderRadius: 14 }}>
          {TABS.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              style={{
                flex: 1,
                padding: '10px 16px',
                borderRadius: 10,
                border: 'none',
                cursor: 'pointer',
                fontSize: 13,
                fontWeight: 600,
                transition: 'all 0.2s',
                background: activeTab === tab.id
                  ? 'linear-gradient(135deg, rgba(139,92,246,0.3), rgba(6,182,212,0.2))'
                  : 'transparent',
                color: activeTab === tab.id ? 'var(--primary-light)' : 'var(--text-secondary)',
                borderBottom: activeTab === tab.id ? '2px solid var(--primary)' : '2px solid transparent',
              }}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </GlassCard>

        {/* Diagram panel */}
        <GlassCard style={{ padding: 24, minHeight: 400 }}>
          {loading ? (
            <div style={{ color: 'var(--text-tertiary)', textAlign: 'center', padding: 60 }}>Loading diagrams…</div>
          ) : (
            activeTab === 'architecture' ? (
              <ArchitectureTab data={activeData} base={base} />
            ) : activeTab === 'dependency_graph' ? (
              <DependencyGraphTab data={activeData} base={base} />
            ) : (
              <ModuleRelationshipsTab data={activeData} base={base} />
            )
          )}
        </GlassCard>

        {/* Legend */}
        <div style={{ display: 'flex', gap: 16, marginTop: 16, flexWrap: 'wrap' }}>
          {COLORS_LIST.map((color) => {
            const c = NODE_COLORS[color];
            return (
              <div key={color} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <div
                  style={{
                    width: 14, height: 14, borderRadius: '50%',
                    background: c.bg,
                    border: `1px solid ${c.border}`,
                  }}
                />
                <span style={{ fontSize: 12, color: 'var(--text-tertiary)', textTransform: 'capitalize' }}>{color}</span>
              </div>
            );
          })}
          <span style={{ fontSize: 12, color: 'var(--text-tertiary)', marginLeft: 'auto' }}>
            Click any node to view its wiki page
          </span>
        </div>
      </div>
    </>
  );
}

