/**
 * GlassCard — frosted glass container matching .glass-card in the mock design system.
 *
 * Mock reference: specs/001-code-wiki/ux/docs-glassmorphism/home.html (.glass-card)
 * Properties verified:
 *   background: rgba(15,15,25,0.7) (--glass-bg)
 *   backdrop-filter: blur(20px)
 *   border: 1px solid rgba(255,255,255,0.1) (--glass-border)
 *   border-radius: 20px (--radius-lg)
 *   box-shadow: 0 8px 32px 0 rgba(0,0,0,0.37) (--shadow-glass)
 */

import { type ReactNode, type CSSProperties } from 'react';

interface GlassCardProps {
  children: ReactNode;
  className?: string;
  style?: CSSProperties;
  as?: keyof JSX.IntrinsicElements;
}

export function GlassCard({
  children,
  className = '',
  style,
  as: Tag = 'div',
}: GlassCardProps) {
  return (
    <Tag className={`glass-card ${className}`} style={style}>
      {children}
    </Tag>
  );
}

/**
 * GradientBackground — three animated gradient orbs matching the glassmorphism mock.
 *
 * Mock reference: specs/001-code-wiki/ux/docs-glassmorphism/home.html
 * CSS classes: .gradient-bg, .gradient-orb, .orb-1/2/3 (defined in globals.css)
 */

export function GradientBackground() {
  return (
    <div className="gradient-bg" aria-hidden="true">
      <div className="gradient-orb orb-1" />
      <div className="gradient-orb orb-2" />
      <div className="gradient-orb orb-3" />
    </div>
  );
}

