                  background: 'none',
                  border: 'none',
                  outline: 'none',
                  color: 'var(--text-primary)',
                  fontFamily: "'Outfit', sans-serif",
                  fontSize: 14,
                }}
              />
            </form>

            <Link
              href={`/${owner}/${name}/chat`}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 8,
                padding: '10px 20px',
                background: 'linear-gradient(135deg, var(--primary), var(--secondary))',
                borderRadius: 12,
                color: 'white',
                fontWeight: 600,
                fontSize: 14,
                textDecoration: 'none',
                flexShrink: 0,
              }}
            >
              💬 Ask AI
            </Link>
          </div>

          {/* Repo info */}
          <h1
            style={{
              fontFamily: "'Fira Code', monospace",
              fontSize: 28,
              fontWeight: 700,
              marginBottom: 10,
            }}
          >
            {name}
          </h1>
          <p style={{ color: 'var(--text-secondary)', marginBottom: 16, maxWidth: 700, lineHeight: 1.6 }}>
            AI-powered code documentation platform that generates and maintains comprehensive,
            structured wiki for any codebase.
          </p>

          {/* Meta chips */}
          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center' }}>
            {[
              { icon: '⚡', label: (repo?.primary_languages?.[0] ?? 'TypeScript') },
              { icon: '🕒', label: repo?.last_analyzed_at ? `Updated ${new Date(repo.last_analyzed_at).toLocaleDateString()}` : 'Last analyzed: 2 hours ago' },
              { icon: '📁', label: `${repo?.size_files?.toLocaleString() ?? '312'} files` },
            ].map((m) => (
              <span
                key={m.label}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 6,
                  padding: '4px 12px',
                  background: 'rgba(255,255,255,0.05)',
                  border: '1px solid var(--glass-border)',
                  borderRadius: 20,
                  fontSize: 13,
                  color: 'var(--text-tertiary)',
                }}
              >
                {m.icon} {m.label}
              </span>
            ))}
          </div>
        </GlassCard>

        {/* ── Stats grid ── */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(4, 1fr)',
            gap: 16,
            marginBottom: 28,
          }}
          className="stagger"
        >
          {[
            { value: moduleCount, label: 'Modules' },
            { value: funcCount, label: 'Functions' },
            { value: classCount, label: 'Classes' },
            { value: loc, label: 'Lines of Code' },
          ].map((s) => (
            <GlassCard
              key={s.label}
              className="animate-fade-in-up"
              style={{ padding: '24px 20px', textAlign: 'center' }}
            >
              <div
                style={{
                  fontSize: 32,
                  fontWeight: 800,
                  background: 'linear-gradient(135deg, var(--primary-light), var(--secondary))',
                  WebkitBackgroundClip: 'text',
                  WebkitTextFillColor: 'transparent',
                  backgroundClip: 'text',
                  marginBottom: 4,
                }}
              >
                {s.value}
              </div>
              <div style={{ fontSize: 13, color: 'var(--text-tertiary)', fontWeight: 500 }}>{s.label}</div>
            </GlassCard>
          ))}
        </div>

        {/* ── Quick links ── */}
        <section style={{ marginBottom: 40 }}>
          <h2 style={{ fontSize: 20, fontWeight: 700, marginBottom: 16 }}>Quick Links</h2>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))',
              gap: 12,
            }}
            className="stagger"
          >
            {QUICK_LINKS.map((link) => (
              <Link
                key={link.href}
                href={`/${owner}/${name}/${link.href}`}
                className="animate-fade-in-up"
                style={{
                  display: 'block',
                  padding: '20px',
                  background: 'var(--glass-bg)',
                  backdropFilter: 'blur(20px)',
                  border: '1px solid var(--glass-border)',
                  borderRadius: 16,
                  textDecoration: 'none',
                  transition: 'all 0.2s',
                }}
                onMouseOver={(e) => {
                  e.currentTarget.style.borderColor = 'rgba(139,92,246,0.4)';
                  e.currentTarget.style.transform = 'translateY(-3px)';
                  e.currentTarget.style.boxShadow = '0 8px 24px rgba(139,92,246,0.15)';
                }}
                onMouseOut={(e) => {
                  e.currentTarget.style.borderColor = 'var(--glass-border)';
                  e.currentTarget.style.transform = 'none';
                  e.currentTarget.style.boxShadow = 'none';
                }}
              >
                <div style={{ fontSize: 22, marginBottom: 8 }}>{link.icon}</div>
                <div style={{ fontSize: 14, fontWeight: 700, color: 'var(--text-primary)', marginBottom: 4 }}>
                  {link.title}
                </div>
                <div style={{ fontSize: 12, color: 'var(--text-tertiary)', lineHeight: 1.5 }}>
                  {link.desc}
                </div>
              </Link>
            ))}
          </div>
        </section>

        {/* ── Modules grid ── */}
        <section style={{ marginBottom: 40 }}>
          <h2 style={{ fontSize: 20, fontWeight: 700, marginBottom: 16 }}>Modules</h2>
          {loading ? (
            <div style={{ textAlign: 'center', color: 'var(--text-tertiary)', padding: 40 }}>
              Loading modules…
            </div>
          ) : (
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
                gap: 16,
              }}
              className="stagger"
            >
              {displayModules.map((mod, i) => (
                <Link
                  key={mod.id}
                  href={`/${owner}/${name}/modules/${mod.slug}`}
                  className="animate-fade-in-up"
                  style={{
                    position: 'relative',
                    display: 'block',
                    padding: 24,
                    background: 'var(--glass-bg)',
                    backdropFilter: 'blur(20px)',
                    border: '1px solid var(--glass-border)',
                    borderRadius: 20,
                    textDecoration: 'none',
                    transition: 'all 0.3s',
                    overflow: 'hidden',
                  }}
                  onMouseOver={(e) => {
                    e.currentTarget.style.transform = 'translateY(-4px)';
                    e.currentTarget.style.borderColor = 'rgba(139,92,246,0.3)';
                    e.currentTarget.style.boxShadow = '0 12px 40px rgba(139,92,246,0.15)';
                  }}
                  onMouseOut={(e) => {
                    e.currentTarget.style.transform = 'none';
                    e.currentTarget.style.borderColor = 'var(--glass-border)';
                    e.currentTarget.style.boxShadow = 'none';
                  }}
                >
                  {/* Accent bar on hover (via gradient pseudo) */}
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
                    <span style={{ fontSize: 24 }}>{MODULE_ICONS[i % MODULE_ICONS.length]}</span>
                    <span
                      style={{
                        fontSize: 11,
                        fontWeight: 600,
                        padding: '3px 10px',
                        borderRadius: 20,
                        background: 'rgba(16,185,129,0.15)',
                        color: '#4ade80',
                        border: '1px solid rgba(16,185,129,0.3)',
                      }}
                    >
                      Active
                    </span>
                  </div>
                  <h3 style={{ fontSize: 16, fontWeight: 700, color: 'var(--text-primary)', marginBottom: 8 }}>
                    {mod.name}
                  </h3>
                  <p style={{ fontSize: 13, color: 'var(--text-tertiary)', lineHeight: 1.6, marginBottom: 16 }}>
                    {mod.description ?? 'No description available.'}
                  </p>
                  <div
                    style={{
                      display: 'flex',
                      gap: 12,
                      fontSize: 12,
                      color: 'var(--text-tertiary)',
                      borderTop: '1px solid var(--glass-border)',
                      paddingTop: 12,
                    }}
                  >
                    {mod.file_count != null && <span><strong style={{ color: 'var(--text-primary)' }}>{mod.file_count}</strong> functions</span>}
                    {mod.file_paths?.[0] && (
                      <span style={{ fontFamily: "'Fira Code', monospace", fontSize: 11 }}>
                        {mod.file_paths[0]}
                      </span>
                    )}
                  </div>
                </Link>
              ))}
            </div>
          )}
        </section>

        {/* ── Recent activity ── */}
        <section>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
            <h2 style={{ fontSize: 20, fontWeight: 700 }}>Recent Activity</h2>
            <button
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 8,
                padding: '10px 20px',
                background: 'rgba(6,182,212,0.15)',
                border: '1px solid rgba(6,182,212,0.35)',
                borderRadius: 12,
                color: 'var(--secondary)',
                fontFamily: "'Outfit', sans-serif",
                fontWeight: 600,
                fontSize: 14,
                cursor: 'pointer',
                transition: 'all 0.2s',
              }}
              onMouseOver={(e) => {
                e.currentTarget.style.background = 'rgba(6,182,212,0.25)';
                e.currentTarget.style.transform = 'translateY(-2px)';
              }}
              onMouseOut={(e) => {
                e.currentTarget.style.background = 'rgba(6,182,212,0.15)';
                e.currentTarget.style.transform = 'none';
              }}
            >
              🔄 Sync Now
            </button>
          </div>

          <GlassCard style={{ padding: '24px 28px' }}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 0 }}>
              {TIMELINE_ITEMS.map((item, i) => (
                <div
                  key={i}
                  style={{
                    display: 'flex',
                    gap: 16,
                    alignItems: 'flex-start',
                    paddingBottom: i < TIMELINE_ITEMS.length - 1 ? 20 : 0,
                    position: 'relative',
                  }}
                >
                  {i < TIMELINE_ITEMS.length - 1 && (
                    <div
                      style={{
                        position: 'absolute',
                        left: 17,
                        top: 36,
                        bottom: 0,
                        width: 2,
                        background: 'var(--glass-border)',
                      }}
                    />
                  )}
                  <div
                    style={{
                      width: 36,
                      height: 36,
                      borderRadius: '50%',
                      background: 'rgba(255,255,255,0.05)',
                      border: '1px solid var(--glass-border)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontSize: 16,
                      flexShrink: 0,
                      position: 'relative',
                      zIndex: 1,
                    }}
                  >
                    {item.icon}
                  </div>
                  <div>
                    <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-primary)', marginBottom: 2 }}>
                      {item.text}
                    </div>
                    <div style={{ fontSize: 12, color: 'var(--text-tertiary)' }}>{item.detail}</div>
                    <div style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 2 }}>{item.time}</div>
                  </div>
                </div>
              ))}
            </div>
          </GlassCard>
        </section>
      </div>
    </>
  );
}

