'use client';

/**
 * API Reference page — alphabetical function/class index.
 * Mock: specs/001-code-wiki/ux/docs-glassmorphism/api-reference.html
 */

import { useState } from 'react';
import { useParams } from 'next/navigation';
import Link from 'next/link';
import { GradientBackground } from '@/components/ui/GradientBackground';
import { GlassCard } from '@/components/ui/GlassCard';
import { Logo } from '@/components/ui/Logo';
import { Breadcrumbs } from '@/components/ui/Breadcrumbs';
import { TypeBadge } from '@/components/ui/TypeBadge';
import { WikiSidebar } from '@/components/layout/WikiSidebar';

const MOCK_ENTRIES = [
  { name: 'authenticate_user', type: 'function' as const, module: 'Authentication', visibility: 'public', signature: 'authenticate_user(username: str, password: str) → AuthResult' },
  { name: 'AuthenticationMiddleware', type: 'class' as const, module: 'Authentication', visibility: 'public', signature: 'class AuthenticationMiddleware(BaseMiddleware)' },
  { name: 'build_call_graph', type: 'function' as const, module: 'Analysis', visibility: 'public', signature: 'build_call_graph(repo_path: str) → nx.DiGraph' },
  { name: 'create_session', type: 'function' as const, module: 'Authentication', visibility: 'public', signature: 'create_session(user_id: str, ttl: int) → str' },
  { name: 'CodeParser', type: 'class' as const, module: 'Analysis', visibility: 'public', signature: 'class CodeParser(language: str)' },
  { name: 'detect_modules', type: 'function' as const, module: 'Analysis', visibility: 'public', signature: 'detect_modules(file_tree: FileTree) → list[Module]' },
  { name: 'embed_text', type: 'function' as const, module: 'Search', visibility: 'internal', signature: 'embed_text(text: str) → list[float]' },
  { name: 'generate_wiki_page', type: 'function' as const, module: 'Wiki', visibility: 'public', signature: 'generate_wiki_page(module: Module) → WikiPage' },
  { name: 'hashPassword', type: 'function' as const, module: 'Utils', visibility: 'internal', signature: 'hashPassword(plain: str) → str' },
  { name: 'logout', type: 'function' as const, module: 'Authentication', visibility: 'public', signature: 'logout(session_id: str) → None' },
  { name: 'refresh_token', type: 'function' as const, module: 'Authentication', visibility: 'public', signature: 'refresh_token(token: str) → str' },
  { name: 'search_entities', type: 'function' as const, module: 'Search', visibility: 'public', signature: 'search_entities(query: str, limit: int) → list[Entity]' },
  { name: 'verify_token', type: 'function' as const, module: 'Authentication', visibility: 'public', signature: 'verify_token(token: str) → Payload' },
];

const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
const TYPES = ['All', 'Functions', 'Classes', 'Methods'];
const MODULES = ['All Modules', 'Authentication', 'Analysis', 'Wiki', 'Search', 'Utils'];
const VISIBILITIES = ['All', 'Public', 'Internal'];

export default function ApiReferencePage() {
  const params = useParams();
  const owner = params.owner as string;
  const name = params.name as string;
  const base = `/${owner}/${name}`;

  const [filter, setFilter] = useState('');
  const [typeFilter, setTypeFilter] = useState('All');
  const [moduleFilter, setModuleFilter] = useState('All Modules');
  const [visFilter, setVisFilter] = useState('All');
  const [view, setView] = useState<'list' | 'grid'>('list');

  const filtered = MOCK_ENTRIES.filter((e) => {
    if (filter && !e.name.toLowerCase().includes(filter.toLowerCase())) return false;
    if (typeFilter !== 'All') {
      if (typeFilter === 'Functions' && e.type !== 'function') return false;
      if (typeFilter === 'Classes' && e.type !== 'class') return false;
    }
    if (moduleFilter !== 'All Modules' && e.module !== moduleFilter) return false;
    if (visFilter !== 'All' && e.visibility !== visFilter.toLowerCase()) return false;
    return true;
  });

  const byLetter = LETTERS.map((l) => ({
    letter: l,
    entries: filtered.filter((e) => e.name[0].toUpperCase() === l),
  })).filter((g) => g.entries.length > 0);

  return (
    <>
      <GradientBackground />
      <div
        className="wiki-layout"
        style={{
          display: 'grid',
          gridTemplateColumns: '280px 1fr',
          minHeight: '100vh',
        }}
      >
        {/* Left sidebar */}
        <WikiSidebar pageTitle={`${name} — API Reference`}>
          <div style={{ padding: '0 20px 24px' }}>
            <Logo href={base} />
          </div>
          {[
            { label: 'Wiki Home', href: '' },
            { label: 'Getting Started', href: 'getting-started' },
            { label: 'API Reference', href: 'api', active: true },
            { label: 'Glossary', href: 'glossary' },
            { label: 'Search', href: 'search' },
          ].map((item) => (
            <Link
              key={item.label}
              href={`${base}/${item.href}`}
              style={{
                display: 'block',
                padding: '8px 20px',
                fontSize: 14,
                fontWeight: 500,
                color: item.active ? 'var(--primary-light)' : 'var(--text-secondary)',
                textDecoration: 'none',
                background: item.active ? 'linear-gradient(135deg, rgba(139,92,246,0.15), rgba(6,182,212,0.1))' : 'transparent',
                borderLeft: item.active ? '3px solid var(--primary)' : '3px solid transparent',
                transition: 'all 0.2s',
              }}
            >
              {item.label}
            </Link>
          ))}
        </WikiSidebar>

        {/* Main content */}
        <main className="wiki-main" style={{ padding: '32px 48px 80px', minWidth: 0 }}>
          <Breadcrumbs crumbs={[{ label: `${name} wiki`, href: base }, { label: 'API Reference' }]} />
          <h1 style={{ fontSize: 32, fontWeight: 800, margin: '24px 0 8px', letterSpacing: '-0.02em' }}>API Reference</h1>
          <p style={{ color: 'var(--text-secondary)', marginBottom: 24 }}>
            Complete index of {MOCK_ENTRIES.length} exported symbols from {name}.
          </p>

          {/* Filters */}
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 24 }}>
            <input
              type="text"
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              placeholder="Filter by name…"
              style={{
                padding: '8px 14px',
                background: 'rgba(255,255,255,0.05)',
                border: '1px solid var(--glass-border)',
                borderRadius: 10,
                color: 'var(--text-primary)',
                fontFamily: "'Outfit', sans-serif",
                fontSize: 13,
                outline: 'none',
                flex: '1 1 180px',
              }}
            />
            {[
              { label: 'Type', value: typeFilter, options: TYPES, set: setTypeFilter },
              { label: 'Module', value: moduleFilter, options: MODULES, set: setModuleFilter },
              { label: 'Visibility', value: visFilter, options: VISIBILITIES, set: setVisFilter },
            ].map(({ label, value, options, set }) => (
              <select
                key={label}
                value={value}
                onChange={(e) => set(e.target.value)}
                style={{
                  padding: '8px 14px',
                  background: 'rgba(255,255,255,0.05)',
                  border: '1px solid var(--glass-border)',
                  borderRadius: 10,
                  color: 'var(--text-primary)',
                  fontFamily: "'Outfit', sans-serif",
                  fontSize: 13,
                  cursor: 'pointer',
                }}
              >
                {options.map((o) => <option key={o} value={o}>{o}</option>)}
              </select>
            ))}
            <div style={{ marginLeft: 'auto', display: 'flex', gap: 4 }}>
              {(['list', 'grid'] as const).map((v) => (
                <button
                  key={v}
                  onClick={() => setView(v)}
                  style={{
                    padding: '8px 14px',
                    borderRadius: 10,
                    fontSize: 13,
                    border: 'none',
                    cursor: 'pointer',
                    fontFamily: "'Outfit', sans-serif",
                    transition: 'all 0.2s',
                    ...(view === v
                      ? { background: 'rgba(139,92,246,0.2)', color: 'var(--primary-light)', border: '1px solid rgba(139,92,246,0.4)' }
                      : { background: 'rgba(255,255,255,0.05)', color: 'var(--text-tertiary)', border: '1px solid var(--glass-border)' }),
                  }}
                >
                  {v === 'list' ? '≡' : '⊞'}
                </button>
              ))}
            </div>
          </div>

          {/* Results count */}
          <p style={{ fontSize: 13, color: 'var(--text-tertiary)', marginBottom: 24 }}>
            Showing {filtered.length} of {MOCK_ENTRIES.length} symbols
          </p>

          {/* Entries */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 32 }}>
            {byLetter.map((group) => (
              <div key={group.letter} id={`api-${group.letter}`}>
                <div
                  style={{
                    fontSize: 18,
                    fontWeight: 800,
                    color: 'var(--primary-light)',
                    fontFamily: "'Fira Code', monospace",
                    marginBottom: 12,
