const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
const TYPES = ['All', 'Functions', 'Classes', 'Methods'];
const VISIBILITIES = ['All', 'Public', 'Internal'];

interface Entry {
  name: string;
  type: 'function' | 'class' | 'method' | 'module' | 'file' | 'variable';
  module: string;
  visibility: string;
  signature: string;
  qualifiedName: string;
}

function toEntry(item: SearchResultItem): Entry {
  const typeHint = item.title.match(/\((\w+)\)$/)?.[1] ?? 'function';
  const validType = ['function', 'class', 'method', 'module', 'file', 'variable'].includes(typeHint)
    ? (typeHint as Entry['type'])
    : 'function';
  const name = item.title.replace(/\s*\(\w+\)$/, '').split('.').pop() ?? item.title;
  return {
    name,
    type: validType,
    module: item.title.split('.').slice(0, -1).join('.') || 'Unknown',
    visibility: 'public',
    signature: item.snippet ?? '',
    qualifiedName: item.id,
  };
}

