'use client';

/**
 * Glossary page — alphabetical term browser built from live code entities.
 * Mock: specs/001-code-wiki/ux/docs-glassmorphism/glossary.html
 */

import { useState, useEffect } from 'react';
import { useParams } from 'next/navigation';
import Link from 'next/link';
import { GradientBackground } from '@/components/ui/GradientBackground';
import { GlassCard } from '@/components/ui/GlassCard';
import { Logo } from '@/components/ui/Logo';
import { Breadcrumbs } from '@/components/ui/Breadcrumbs';
import { WikiSidebar } from '@/components/layout/WikiSidebar';
import { api } from '@/services/api';
import type { SearchResultItem } from '@/services/api';

interface GlossaryTerm {
  name: string;
  type: string;
  desc: string;
}

interface LetterGroup {
  letter: string;
  terms: GlossaryTerm[];
}

const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');

function entityTypeLabel(raw: string): string {
  const map: Record<string, string> = {
    function: 'Function',
    class: 'Class',
    method: 'Method',
    module: 'Module',
    file: 'File',
    variable: 'Variable',
  };
  const typeHint = raw.match(/\((\w+)\)$/)?.[1] ?? '';
  return map[typeHint] ?? 'Symbol';
}

function toTerms(results: SearchResultItem[]): LetterGroup[] {
  const byLetter: Record<string, GlossaryTerm[]> = {};

  for (const item of results) {
    const name = item.title.replace(/\s*\(\w+\)$/, '').split('.').pop() ?? item.title;
    if (!name) continue;
