  ]},
  { letter: 'C', terms: [
    { name: 'Call Graph', type: 'Analysis', desc: 'A directed graph that represents calling relationships between subroutines in a program.' },
    { name: 'CODEOWNERS', type: 'DevOps', desc: 'A file that defines ownership of code files in a repository, used for automatic review assignments.' },
  ]},
  { letter: 'D', terms: [
    { name: 'Dossier', type: 'Architecture', desc: 'The shared LangGraph state object that all facet agents read from and write to during analysis.' },
    { name: 'Dependency Graph', type: 'Analysis', desc: 'A directed graph showing module relationships and import dependencies within a codebase.' },
  ]},
  { letter: 'F', terms: [
    { name: 'Facet Intelligence', type: 'Architecture', desc: 'Specialist agents that each analyze one dimension of a repository (security, CI/CD, architecture, etc.).' },
  ]},
  { letter: 'J', terms: [
    { name: 'JWT', type: 'Security', desc: 'JSON Web Token — a compact, URL-safe means of representing claims between two parties.' },
  ]},
  { letter: 'M', terms: [
    { name: 'Module', type: 'Core Concept', desc: 'A logical grouping of related source files that provides a coherent unit of functionality.' },
