  // relationships.imports = modules/files this entity imports
  const callees: string[] = entity?.relationships?.calls ?? [];
  const imports: string[] = entity?.relationships?.imports ?? [];

  const tableStyle: React.CSSProperties = {
    width: '100%',
    borderCollapse: 'collapse' as const,
    fontSize: 14,
    marginBottom: 8,
  };

  const thStyle: React.CSSProperties = {
    textAlign: 'left',
    padding: '10px 14px',
    fontSize: 12,
    fontWeight: 700,
    textTransform: 'uppercase',
    letterSpacing: '0.05em',
    color: 'var(--text-tertiary)',
    borderBottom: '1px solid var(--glass-border)',
    background: 'rgba(255,255,255,0.03)',
  };

  const tdStyle: React.CSSProperties = {
    padding: '12px 14px',
    borderBottom: '1px solid var(--glass-border)',
    color: 'var(--text-secondary)',
    verticalAlign: 'top',
  };

  return (
    <>
      <GradientBackground />

      <div
        className="wiki-layout"
        style={{
          display: 'grid',
          gridTemplateColumns: '280px 1fr 260px',
          minHeight: '100vh',
        }}
      >
        {/* ── Left sidebar ── */}
        <WikiSidebar pageTitle={`${name} — ${displayName}`}>
          <div style={{ padding: '0 20px 20px' }}>
            <Logo href={base} />
          </div>

          {/* Back to module */}
          <div style={{ padding: '0 20px 16px' }}>
            <Link
              href={`${base}/modules/auth`}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 6,
                fontSize: 13,
                color: 'var(--text-tertiary)',
                textDecoration: 'none',
                transition: 'color 0.2s',
              }}
            >
              ← Authentication Module
            </Link>
          </div>

          {SIDEBAR_SECTIONS.map((section) => (
            <div key={section.label} style={{ marginBottom: 8 }}>
              <div
                style={{
                  padding: '6px 20px',
                  fontSize: 11,
                  fontWeight: 700,
                  textTransform: 'uppercase',
                  letterSpacing: '0.8px',
                  color: 'var(--text-tertiary)',
                }}
              >
                {section.label}
              </div>
              {section.items.map((item) => (
                <Link
                  key={item.label}
                  href={`${base}/${item.href}`}
                  style={{
                    display: 'block',
                    padding: '8px 20px',
                    fontSize: 14,
                    fontWeight: 500,
                    color: 'var(--text-secondary)',
                    textDecoration: 'none',
                    transition: 'color 0.2s',
                  }}
                >
                  {item.label}
                </Link>
              ))}
            </div>
          ))}
        </WikiSidebar>

        {/* ── Main content ── */}
        <main
          className="wiki-main"
          style={{
            padding: '32px 44px',
            minWidth: 0,
            background: 'var(--glass-bg)',
            backdropFilter: 'blur(20px)',
            borderRight: '1px solid var(--glass-border)',
          }}
        >
          <Breadcrumbs
            crumbs={[
              { label: `${name} wiki`, href: base },
              { label: 'Modules', href: `${base}/modules` },
              { label: 'Authentication', href: `${base}/modules/auth` },
              { label: displayName },
            ]}
          />

          {/* Function header */}
          <div style={{ marginTop: 28, marginBottom: 32 }}>
            <TypeBadge type={displayType as 'function' | 'class' | 'method' | 'module'} style={{ marginBottom: 12 }} />
            <h1
              style={{
                fontFamily: "'Fira Code', monospace",
                fontSize: 30,
                fontWeight: 700,
                letterSpacing: '-0.02em',
                marginBottom: 12,
              }}
            >
              {displayName}
            </h1>
