            style={{
              background: 'rgba(255,255,255,0.02)',
              border: '1px solid var(--glass-border)',
              borderRadius: 12,
              overflow: 'hidden',
              marginBottom: 32,
            }}
          >
            <table style={tableStyle}>
              <thead>
                <tr>
                  {['Name', 'Type', 'Description', 'Required'].map((h) => (
                    <th key={h} style={thStyle}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {MOCK_PARAMS.map((p) => (
                  <tr key={p.name}>
                    <td style={tdStyle}>
                      <code style={{ fontFamily: "'Fira Code', monospace", color: 'var(--primary-light)', fontSize: 13 }}>
                        {p.name}
                      </code>
                    </td>
                    <td style={tdStyle}>
                      <code style={{ fontFamily: "'Fira Code', monospace", color: '#10B981', fontSize: 13 }}>
                        {p.type}
                      </code>
                    </td>
                    <td style={{ ...tdStyle, color: 'var(--text-tertiary)' }}>{p.desc}</td>
                    <td style={tdStyle}>
                      <span
                        style={{
                          padding: '2px 8px',
                          borderRadius: 6,
                          fontSize: 11,
                          fontWeight: 700,
                          ...(p.required
                            ? { background: 'rgba(139,92,246,0.15)', color: 'var(--primary-light)', border: '1px solid rgba(139,92,246,0.3)' }
                            : { background: 'rgba(255,255,255,0.05)', color: 'var(--text-tertiary)', border: '1px solid var(--glass-border)' }),
                        }}
                      >
                        {p.required ? 'Yes' : 'No'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Return Value */}
          <h2 id="return-value" style={{ fontSize: 20, fontWeight: 700, marginBottom: 14 }}>
            Return Value
          </h2>
          <div
            style={{
              background: 'rgba(255,255,255,0.02)',
              border: '1px solid var(--glass-border)',
              borderRadius: 12,
              overflow: 'hidden',
              marginBottom: 32,
            }}
          >
            <table style={tableStyle}>
              <thead>
                <tr>
                  {['Type', 'Description'].map((h) => (
                    <th key={h} style={thStyle}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td style={{ ...tdStyle, whiteSpace: 'nowrap' }}>
                    <code style={{ fontFamily: "'Fira Code', monospace", color: '#10B981', fontSize: 13 }}>
                      Promise&lt;AuthResult&gt;
                    </code>
                  </td>
                  <td style={{ ...tdStyle, color: 'var(--text-tertiary)' }}>
                    Returns a promise resolving to an <code style={{ fontFamily: "'Fira Code', monospace" }}>AuthResult</code> object with:
                    <ul style={{ marginTop: 8, paddingLeft: 20 }}>
                      {['success (boolean)', 'token (string | null)', 'user (User | null)', 'error (string | null)'].map((f) => (
                        <li key={f} style={{ fontSize: 13, marginBottom: 4 }}>{f}</li>
                      ))}
                    </ul>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          {/* Usage Examples */}
          <h2 id="examples" style={{ fontSize: 20, fontWeight: 700, marginBottom: 14 }}>
            Usage Examples
          </h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 16, marginBottom: 32 }}>
            {[
              {
                title: 'Basic Authentication',
                code: `import { authenticateUser } from './auth/authenticator';\n\nasync function handleLogin(username: string, password: string) {\n  const result = await authenticateUser(username, password);\n\n  if (result.success) {\n    console.log('Login successful!', result.user);\n    return result.token;\n  } else {\n    console.error('Login failed:', result.error);\n    return null;\n  }\n}`,
              },
              {
                title: 'With Custom Options',
                code: `const result = await authenticateUser(\n  'user@example.com',\n  'securePassword123',\n  {\n    sessionDuration: 3600, // 1 hour in seconds\n    requireMFA: true,\n    deviceFingerprint: getDeviceFingerprint()\n  }\n);\n\nif (result.success && result.requiresMFA) {\n  redirectToMFA(result.mfaToken);\n}`,
              },
            ].map((ex) => (
              <div key={ex.title}>
                <div
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: 'var(--text-tertiary)',
                    marginBottom: 8,
                    textTransform: 'uppercase',
                    letterSpacing: '0.05em',
                  }}
                >
                  {ex.title}
                </div>
                <CodeBlock language="typescript">{ex.code}</CodeBlock>
              </div>
            ))}
          </div>

          {/* Call graph */}
          {[
            { id: 'called-by', title: 'Called By', items: MOCK_CALLERS },
            { id: 'calls', title: 'Calls', items: MOCK_CALLEES },
          ].map((group) => (
            <div key={group.id}>
              <h2 id={group.id} style={{ fontSize: 20, fontWeight: 700, marginBottom: 14 }}>
                {group.title}
              </h2>
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))',
                  gap: 12,
                  marginBottom: 32,
                }}
              >
                {group.items.map((item) => (
                  <Link
                    key={item.name}
                    href={`${base}/entities/${item.name.replace('()', '')}`}
                    style={{
                      padding: '16px',
                      background: 'rgba(255,255,255,0.03)',
                      border: '1px solid var(--glass-border)',
                      borderRadius: 12,
                      textDecoration: 'none',
                      transition: 'all 0.2s',
                    }}
                    onMouseOver={(e) => {
                      e.currentTarget.style.borderColor = 'rgba(6,182,212,0.4)';
                      e.currentTarget.style.background = 'rgba(6,182,212,0.05)';
                    }}
                    onMouseOut={(e) => {
                      e.currentTarget.style.borderColor = 'var(--glass-border)';
                      e.currentTarget.style.background = 'rgba(255,255,255,0.03)';
                    }}
                  >
                    <div
                      style={{
                        fontFamily: "'Fira Code', monospace",
                        fontSize: 13,
                        color: 'var(--secondary)',
                        fontWeight: 600,
                        marginBottom: 6,
                      }}
                    >
                      {item.name}
                    </div>
                    <div style={{ fontSize: 12, color: 'var(--text-tertiary)' }}>
                      {item.location}
                    </div>
                  </Link>
                ))}
              </div>
            </div>
          ))}

          {/* Source Code */}
          <h2 id="source" style={{ fontSize: 20, fontWeight: 700, marginBottom: 14 }}>
            Source Code
          </h2>
          <CodeBlock language="typescript">
            {`async function ${displayName}(\n  username: string,\n  password: string,\n  options?: AuthOptions\n): Promise<AuthResult> {\n  const user = await findUserByCredentials(username);\n  if (!user) return { success: false, error: 'INVALID_CREDENTIALS' };\n\n  const valid = await hashPassword.verify(password, user.passwordHash);\n  if (!valid) return { success: false, error: 'INVALID_CREDENTIALS' };\n\n  const token = await generateJWT({ userId: user.id }, options);\n  return { success: true, token, user };\n}`}
          </CodeBlock>
        </main>

        {/* ── Right TOC ── */}
        <aside
          style={{
            position: 'sticky',
            top: 0,
            height: '100vh',
            overflowY: 'auto',
            padding: '32px 20px',
          }}
        >
          <TableOfContents items={TOC_ITEMS} />
        </aside>
      </div>
    </>
  );
}

