'use client';

/**
 * API Reference page — alphabetical function/class index.
 * Mock: specs/001-code-wiki/ux/docs-glassmorphism/api-reference.html
 */

import { useState, useEffect } from 'react';
import { useParams } from 'next/navigation';
import Link from 'next/link';
import { GradientBackground } from '@/components/ui/GradientBackground';
import { GlassCard } from '@/components/ui/GlassCard';
import { Logo } from '@/components/ui/Logo';
import { Breadcrumbs } from '@/components/ui/Breadcrumbs';
import { TypeBadge } from '@/components/ui/TypeBadge';
import { WikiSidebar } from '@/components/layout/WikiSidebar';
import { api } from '@/services/api';
import type { SearchResultItem } from '@/services/api';

const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
const TYPES = ['All', 'Functions', 'Classes', 'Methods'];
const VISIBILITIES = ['All', 'Public', 'Internal'];

interface Entry {
  name: string;
  type: 'function' | 'class' | 'method' | 'module' | 'file' | 'variable';
  module: string;
  visibility: string;
  signature: string;
  qualifiedName: string;
}

function toEntry(item: SearchResultItem): Entry {
  const typeHint = item.title.match(/\((\w+)\)$/)?.[1] ?? 'function';
  const validType = ['function', 'class', 'method', 'module', 'file', 'variable'].includes(typeHint)
    ? (typeHint as Entry['type'])
    : 'function';
  const name = item.title.replace(/\s*\(\w+\)$/, '').split('.').pop() ?? item.title;
  return {
    name,
    type: validType,
    module: item.title.split('.').slice(0, -1).join('.') || 'Unknown',
    visibility: 'public',
    signature: item.snippet ?? '',
    qualifiedName: item.id,
  };
}

export default function ApiReferencePage() {
  const params = useParams();
  const owner = params.owner as string;
  const name = params.name as string;
  const base = `/${owner}/${name}`;

  const [entries, setEntries] = useState<Entry[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('');
  const [typeFilter, setTypeFilter] = useState('All');
  const [visFilter, setVisFilter] = useState('All');
  const [view, setView] = useState<'list' | 'grid'>('list');

  useEffect(() => {
    const load = async () => {
      try {
        const { repositories } = await api.repositories.list();
        const repo = repositories.find(
          (r) => r.owner?.toLowerCase() === owner.toLowerCase() && r.name.toLowerCase() === name.toLowerCase()
        );
        if (!repo) return;

        const results = await api.search.query(repo.id, '', 'entities', 200);
        setEntries(results.results.map(toEntry));
      } catch {
        // leave empty — empty state shown below
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [owner, name]);

  const modules = ['All Modules', ...Array.from(new Set(entries.map((e) => e.module))).sort()];
  const [moduleFilter, setModuleFilter] = useState('All Modules');

  const filtered = entries.filter((e) => {
    if (filter && !e.name.toLowerCase().includes(filter.toLowerCase())) return false;
    if (typeFilter !== 'All') {
      if (typeFilter === 'Functions' && e.type !== 'function') return false;
      if (typeFilter === 'Classes' && e.type !== 'class') return false;
      if (typeFilter === 'Methods' && e.type !== 'method') return false;
    }
    if (moduleFilter !== 'All Modules' && e.module !== moduleFilter) return false;
    if (visFilter !== 'All' && e.visibility !== visFilter.toLowerCase()) return false;
    return true;
  });

  const byLetter = LETTERS.map((l) => ({
    letter: l,
    entries: filtered.filter((e) => e.name[0]?.toUpperCase() === l),
  })).filter((g) => g.entries.length > 0);

  return (
    <>
      <GradientBackground />
      <div
        className="wiki-layout"
        style={{
          display: 'grid',
          gridTemplateColumns: '280px 1fr',
          minHeight: '100vh',
        }}
      >
        {/* Left sidebar */}
        <WikiSidebar pageTitle={`${name} — API Reference`}>
          <div style={{ padding: '0 20px 24px' }}>
            <Logo href={base} />
          </div>
          {[
            { label: 'Wiki Home', href: '' },
            { label: 'Getting Started', href: 'getting-started' },
            { label: 'API Reference', href: 'api', active: true },
            { label: 'Glossary', href: 'glossary' },
            { label: 'Search', href: 'search' },
          ].map((item) => (
            <Link
              key={item.label}
              href={`${base}/${item.href}`}
              style={{
                display: 'block',
                padding: '8px 20px',
                fontSize: 14,
                fontWeight: 500,
                color: item.active ? 'var(--primary-light)' : 'var(--text-secondary)',
                textDecoration: 'none',
                background: item.active ? 'linear-gradient(135deg, rgba(139,92,246,0.15), rgba(6,182,212,0.1))' : 'transparent',
                borderLeft: item.active ? '3px solid var(--primary)' : '3px solid transparent',
                transition: 'all 0.2s',
              }}
            >
              {item.label}
            </Link>
          ))}
        </WikiSidebar>

        {/* Main content */}
        <main className="wiki-main" style={{ padding: '32px 48px 80px', minWidth: 0 }}>
          <Breadcrumbs crumbs={[{ label: `${name} wiki`, href: base }, { label: 'API Reference' }]} />
          <h1 style={{ fontSize: 32, fontWeight: 800, margin: '24px 0 8px', letterSpacing: '-0.02em' }}>API Reference</h1>
          <p style={{ color: 'var(--text-secondary)', marginBottom: 24 }}>
            {loading
              ? 'Loading symbols…'
              : `Complete index of ${entries.length} exported symbols from ${name}.`}
          </p>

          {/* Filters */}
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 24 }}>
            <input
              type="text"
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              placeholder="Filter by name…"
              style={{
                padding: '8px 14px',
                background: 'rgba(255,255,255,0.05)',
                border: '1px solid var(--glass-border)',
                borderRadius: 10,
                color: 'var(--text-primary)',
                fontFamily: "'Outfit', sans-serif",
                fontSize: 13,
                outline: 'none',
                flex: '1 1 180px',
              }}
            />
            {[
              { label: 'Type', value: typeFilter, options: TYPES, set: setTypeFilter },
              { label: 'Module', value: moduleFilter, options: modules, set: setModuleFilter },
              { label: 'Visibility', value: visFilter, options: VISIBILITIES, set: setVisFilter },
            ].map(({ label, value, options, set }) => (
              <select
                key={label}
                value={value}
                onChange={(e) => set(e.target.value)}
                style={{
                  padding: '8px 14px',
                  background: 'rgba(255,255,255,0.05)',
                  border: '1px solid var(--glass-border)',
                  borderRadius: 10,
                  color: 'var(--text-primary)',
                  fontFamily: "'Outfit', sans-serif",
                  fontSize: 13,
                  cursor: 'pointer',
                }}
              >
                {options.map((o) => <option key={o} value={o}>{o}</option>)}
              </select>
            ))}
            <div style={{ marginLeft: 'auto', display: 'flex', gap: 4 }}>
              {(['list', 'grid'] as const).map((v) => (
                <button
                  key={v}
                  onClick={() => setView(v)}
                  style={{
                    padding: '8px 14px',
                    borderRadius: 10,
                    fontSize: 13,
                    border: 'none',
                    cursor: 'pointer',
                    fontFamily: "'Outfit', sans-serif",
                    transition: 'all 0.2s',
                    ...(view === v
                      ? { background: 'rgba(139,92,246,0.2)', color: 'var(--primary-light)', border: '1px solid rgba(139,92,246,0.4)' }
                      : { background: 'rgba(255,255,255,0.05)', color: 'var(--text-tertiary)', border: '1px solid var(--glass-border)' }),
                  }}
                >
                  {v === 'list' ? '≡' : '⊞'}
                </button>
              ))}
            </div>
          </div>

          {/* Results count */}
          {!loading && (
            <p style={{ fontSize: 13, color: 'var(--text-tertiary)', marginBottom: 24 }}>
              Showing {filtered.length} of {entries.length} symbols
            </p>
          )}

          {/* Loading skeleton */}
          {loading && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {[1, 2, 3, 4, 5].map((i) => (
                <div
                  key={i}
                  style={{
                    height: 48,
                    borderRadius: 10,
                    background: 'rgba(255,255,255,0.04)',
                    border: '1px solid var(--glass-border)',
                    animation: 'pulse 1.5s ease-in-out infinite',
                    opacity: 1 - i * 0.12,
                  }}
                />
              ))}
            </div>
          )}

          {/* Entries */}
          {!loading && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 32 }}>
              {byLetter.map((group) => (
                <div key={group.letter} id={`api-${group.letter}`}>
                  <div
                    style={{
                      fontSize: 18,
                      fontWeight: 800,
                      color: 'var(--primary-light)',
                      fontFamily: "'Fira Code', monospace",
                      marginBottom: 12,
                      display: 'flex',
                      alignItems: 'center',
                      gap: 12,
                    }}
                  >
                    {group.letter}
                    <span style={{ flex: 1, height: 1, background: 'var(--glass-border)' }} />
                  </div>
                  <div
                    style={
                      view === 'grid'
                        ? { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 12 }
                        : { display: 'flex', flexDirection: 'column', gap: 8 }
                    }
                  >
                    {group.entries.map((entry) => (
                      <Link
                        key={entry.qualifiedName}
                        href={`${base}/entities/${encodeURIComponent(entry.qualifiedName)}`}
                        style={{ textDecoration: 'none' }}
                      >
                        <div
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 12,
                            padding: view === 'list' ? '12px 16px' : '16px',
                            background: 'rgba(255,255,255,0.03)',
                            border: '1px solid var(--glass-border)',
                            borderRadius: 10,
                            transition: 'all 0.2s',
                            flexWrap: 'wrap',
                          }}
                          onMouseOver={(e) => {
                            e.currentTarget.style.borderColor = 'rgba(139,92,246,0.3)';
                            e.currentTarget.style.background = 'rgba(139,92,246,0.05)';
                          }}
                          onMouseOut={(e) => {
                            e.currentTarget.style.borderColor = 'var(--glass-border)';
                            e.currentTarget.style.background = 'rgba(255,255,255,0.03)';
                          }}
                        >
                          <TypeBadge type={entry.type} />
                          <span
                            style={{
                              fontFamily: "'Fira Code', monospace",
                              fontSize: 14,
                              fontWeight: 600,
                              color: 'var(--text-primary)',
                              flex: view === 'list' ? '0 0 auto' : undefined,
                            }}
                          >
                            {entry.name}
                          </span>
                          {view === 'list' && entry.signature && (
                            <span style={{ fontSize: 12, color: 'var(--text-tertiary)', fontFamily: "'Fira Code', monospace", flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                              {entry.signature}
                            </span>
                          )}
                          <span
                            style={{
                              marginLeft: 'auto',
                              padding: '2px 8px',
                              borderRadius: 6,
                              fontSize: 11,
                              fontWeight: 600,
                              background: 'rgba(255,255,255,0.05)',
                              color: 'var(--text-tertiary)',
                              border: '1px solid var(--glass-border)',
                              flexShrink: 0,
                            }}
                          >
                            {entry.module}
                          </span>
                        </div>
                      </Link>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}

          {!loading && byLetter.length === 0 && (
            <GlassCard style={{ padding: 60, textAlign: 'center' }}>
              <p style={{ fontSize: 32, marginBottom: 12 }}>📭</p>
              <p style={{ color: 'var(--text-tertiary)', fontSize: 15 }}>
                {entries.length === 0
                  ? 'No symbols indexed yet — analysis may still be running.'
                  : 'No symbols match your filters.'}
              </p>
            </GlassCard>
          )}
        </main>
      </div>
    </>
  );
}

