/**
 * GlassCard — frosted glass container matching .glass-card in the mock design system.
 *
 * Mock reference: specs/001-code-wiki/ux/docs-glassmorphism/home.html (.glass-card)
 * Properties verified:
 *   background: rgba(15,15,25,0.7) (--glass-bg)
 *   backdrop-filter: blur(20px)
 *   border: 1px solid rgba(255,255,255,0.1) (--glass-border)
 *   border-radius: 20px (--radius-lg)
 *   box-shadow: 0 8px 32px 0 rgba(0,0,0,0.37) (--shadow-glass)
 */

import { type ReactNode, type CSSProperties } from 'react';

interface GlassCardProps {
  children: ReactNode;
  className?: string;
  style?: CSSProperties;
  as?: keyof JSX.IntrinsicElements;
}

export function GlassCard({
  children,
  className = '',
  style,
  as: Tag = 'div',
}: GlassCardProps) {
  return (
    <Tag className={`glass-card ${className}`} style={style}>
      {children}
    </Tag>
  );
}

/**
 * TypeBadge — entity type color badges matching mock type styling.
 * Types: function (secondary/cyan), class (primary/purple), method (accent/pink),
 *        module (warning/amber), interface (success/green), variable (tertiary).
 */

type EntityType = 'function' | 'class' | 'method' | 'module' | 'interface' | 'variable';

interface TypeBadgeProps {
  type: string;
}

const TYPE_STYLES: Record<EntityType, { bg: string; color: string; border: string }> = {
  function: {
    bg: 'rgba(6,182,212,0.15)',
    color: 'var(--secondary)',
    border: 'rgba(6,182,212,0.3)',
  },
  class: {
    bg: 'rgba(139,92,246,0.15)',
    color: 'var(--primary-light)',
    border: 'rgba(139,92,246,0.3)',
  },
  method: {
    bg: 'rgba(236,72,153,0.15)',
    color: 'var(--accent)',
    border: 'rgba(236,72,153,0.3)',
  },
  module: {
    bg: 'rgba(245,158,11,0.15)',
    color: '#F59E0B',
    border: 'rgba(245,158,11,0.3)',
  },
  interface: {
    bg: 'rgba(16,185,129,0.15)',
    color: 'var(--success)',
    border: 'rgba(16,185,129,0.3)',
  },
  variable: {
    bg: 'rgba(156,163,175,0.15)',
    color: 'var(--text-tertiary)',
    border: 'rgba(156,163,175,0.3)',
  },
};

const DEFAULT_STYLE = {
  bg: 'rgba(156,163,175,0.1)',
  color: 'var(--text-tertiary)',
  border: 'rgba(156,163,175,0.2)',
};

export function TypeBadge({ type }: TypeBadgeProps) {
  const style = TYPE_STYLES[type as EntityType] ?? DEFAULT_STYLE;
