'use client';

/**
 * CodeBlock — Fira Code, dark bg, copy button matching mock pre/code styles.
 * Mock: specs/001-code-wiki/ux/docs-glassmorphism/module.html
 */

import { useState } from 'react';

interface CodeBlockProps {
  code: string;
  language?: string;
}

export function CodeBlock({ code, language }: CodeBlockProps) {
  const [copied, setCopied] = useState(false);

  const copy = async () => {
    await navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div style={{ position: 'relative', margin: '32px 0' }}>
      {/* Language label */}
      {language && (
        <div
          style={{
            position: 'absolute',
            top: 12,
            left: 24,
            fontSize: 12,
            fontFamily: "'Fira Code', monospace",
            color: 'var(--text-tertiary)',
            letterSpacing: '0.05em',
            textTransform: 'lowercase',
          }}
        >
          {language}
        </div>
      )}

      {/* Copy button */}
      <button
        onClick={copy}
        style={{
          position: 'absolute',
          top: 12,
          right: 16,
          background: 'rgba(139,92,246,0.15)',
          border: '1px solid rgba(139,92,246,0.3)',
          borderRadius: 8,
          color: copied ? 'var(--success)' : 'var(--primary-light)',
          fontFamily: "'Outfit', sans-serif",
          fontSize: 12,
          fontWeight: 600,
          padding: '4px 12px',
          cursor: 'pointer',
          transition: 'all 0.2s',
        }}
      >
        {copied ? '✓ Copied' : 'Copy'}
      </button>

      <pre
        style={{
          background: 'rgba(5,5,8,0.8)',
          padding: '28px',
          paddingTop: language ? '48px' : '28px',
          borderRadius: 16,
          overflowX: 'auto',
          fontFamily: "'Fira Code', monospace",
          fontSize: 14,
          lineHeight: 1.8,
          border: '1px solid var(--glass-border)',
          boxShadow: '0 8px 32px rgba(0,0,0,0.5)',
        }}
      >
        <code style={{ color: '#E5E7EB', background: 'none', border: 'none', padding: 0 }}>
          {code}
        </code>
      </pre>
    </div>
  );
}

'use client';

/**
 * TableOfContents — scroll-spy TOC matching mock .toc-item styles.
 *
 * Mock reference: specs/001-code-wiki/ux/docs-glassmorphism/module.html
 * Active item: color = primary-light, gradient left border (height 100%).
 */

import { useEffect, useState } from 'react';
import styles from './TableOfContents.module.css';

export interface TocEntry {
  id: string;
  label: string;
  level?: 2 | 3;
}

interface TableOfContentsProps {
  entries: TocEntry[];
}

export function TableOfContents({ entries }: TableOfContentsProps) {
  const [activeId, setActiveId] = useState<string>('');

  useEffect(() => {
    const observer = new IntersectionObserver(
      (obs) => {
        // Find topmost visible heading
        const visible = obs.filter((e) => e.isIntersecting);
        if (visible.length > 0) {
          setActiveId(visible[0].target.id);
        }
      },
      { rootMargin: '-10% 0px -80% 0px', threshold: 0 }
    );

    entries.forEach(({ id }) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [entries]);

  if (entries.length === 0) return null;

  return (
    <nav className={styles.tocNav}>
      <h4 className={styles.tocTitle}>On This Page</h4>
      <div className={styles.tocList}>
        {entries.map(({ id, label, level = 2 }) => (
          <a
            key={id}
            href={`#${id}`}
            className={`${styles.tocItem} ${level === 3 ? styles.level3 : ''} ${
              activeId === id ? styles.active : ''
            }`}
          >
            {label}
          </a>
        ))}
      </div>
    </nav>
  );
}

